import {object,clone} from '../document/model.js';
import {evaluated,setProperty} from '../animation/evaluate.js';
function finitePoint(p){if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.y))throw Error('Choose finite limb point coordinates.');return {x:p.x,y:p.y};}
export function rubberHoseNodes(start,bend,end){const a=finitePoint(start),b=finitePoint(bend),c=finitePoint(end),dx=c.x-a.x,dy=c.y-a.y,length=Math.hypot(dx,dy),t=length?{x:dx/length,y:dy/length}:{x:1,y:0},left=Math.hypot(b.x-a.x,b.y-a.y)/3,right=Math.hypot(c.x-b.x,c.y-b.y)/3;return [{...a,in:{...a},out:{x:a.x+(b.x-a.x)/3,y:a.y+(b.y-a.y)/3}},{...b,in:{x:b.x-t.x*left,y:b.y-t.y*left},out:{x:b.x+t.x*right,y:b.y+t.y*right}},{...c,in:{x:c.x+(b.x-c.x)/3,y:c.y+(b.y-c.y)/3},out:{...c}}];}
export function createRubberHose({start={x:0,y:0},bend={x:90,y:60},end={x:180,y:0},width=24,color='#282734',...props}={}){if(!Number.isFinite(width)||width<=0||width>4096)throw Error('Limb width must be between 0 and 4096 pixels.');return object('path',{name:'Rubber hose limb',fill:'none',stroke:color,strokeWidth:width,lineCap:'round',lineJoin:'round',strokeProfile:'uniform',closed:false,...props,rubberhose:true,nodes:rubberHoseNodes(start,bend,end)});}
export function rubberHoseGeometry(n,time=0){const v=evaluated(n,time);if(!n.rubberhose||v.nodes?.length!==3)throw Error('Choose a three-point rubber hose limb.');return {start:finitePoint(v.nodes[0]),bend:finitePoint(v.nodes[1]),end:finitePoint(v.nodes[2]),width:v.strokeWidth};}
export function updateRubberHose(n,changes,time=0){const geometry={...rubberHoseGeometry(n,time),...clone(changes)};if(changes.width!==undefined&&(!Number.isFinite(geometry.width)||geometry.width<=0||geometry.width>4096))throw Error('Limb width must be between 0 and 4096 pixels.');const nodes=rubberHoseNodes(geometry.start,geometry.bend,geometry.end);if(['start','bend','end'].some(k=>changes[k]!==undefined))setProperty(n,'nodes',nodes,time);if(changes.width!==undefined)setProperty(n,'strokeWidth',geometry.width,time);return geometry;}
